entries[129914] = { ["name"] = "Horridons Balg", ["text"] = "Questgegenstand\n\"Die Reptilienhaut ist zäher als so manche Plattenrüstung.\"" }
entries[129915] = { ["name"] = "Schuppe von Nethergroll", ["text"] = "Questgegenstand\n\"Eine geisterhafte Schuppe, die gerade so noch an ihrer Körperlichkeit festhält.\"" }
entries[129916] = { ["name"] = "Schuppe von Sartharion", ["text"] = "Questgegenstand\n\"Die Schuppen des schwarzen Drachenschwarms behalten fast immer ihre Hitze.\"" }
entries[129917] = { ["name"] = "Schuppe von Garalon", ["text"] = "Questgegenstand\n\"Garalons Chitinschuppen sind beinahe unmöglich zu entfernen.\"" }
entries[129920] = { ["name"] = "Fenryrs Balg", ["text"] = "Questgegenstand\n\"Überraschend kuschlig.\"" }
entries[129921] = { ["name"] = "Schuppe von Serpentrix", ["text"] = "Questgegenstand\n\"Wie Diamantsplitter.\"" }
entries[129922] = { ["name"] = "Zaumzeug des eisenbeschlagenen Geisterstürmers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen eisenbeschlagenen Geisterstürmer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der ätherische Geist lässt sich kaum von der eisernen Hülle kontrollieren. Diese mächtigen Hengste sind die vorletzte Kreation von Salanar dem Reiter, von der man einst dachte, sie sei vollständig ausgelöscht worden.\"\nVerkäufer:\nAuzin\nZone:\nDalaran\nKosten:\n5.000" }
entries[129923] = { ["name"] = "Zügel des Drachenfalken der Mondfinsternis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachenfalken der Mondfinsternis oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese erhabenen Tiere werden von den abtrünnigen Blutelfen der Stätte der Mondfinsternis eingefangen und waren heißbegehrt bei den Sehern, die am Sanktum der Sterne stationiert waren.\"\nVerkäufer:\nCupri\nZone:\nShattrath\nKosten:\n5.000" }
entries[129926] = { ["name"] = "Mal der Aschenzungen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verkleidet Euch als Zerschlagener der Aschenzungen. (30 Min Abklingzeit)" }
entries[129927] = { ["name"] = "Teuflischer Wetzstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Clevere Nachkonstruktion und Verzauberung eines einfachen Steins haben ein interessantes Resultat hervorgebracht, das den verursachten körperlichen Schaden 5 Min. lang um 5% erhöht. Funktioniert nicht bei Spielercharakteren über Stufe 49. (3 Sek. Abklingzeit)\n\"Der Nachbau von Waffen der Legion hat interessante Ergebnisse erzielt.\"" }
entries[129928] = { ["name"] = "Kaltes zeitverzerrtes Prisma", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[129929] = { ["name"] = "Spiegel der Möglichkeiten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Deckt Berührungspunkte zwischen Draenor und der Scherbenwelt auf. (15 Sek. Abklingzeit)\n\"Manche Spiegel zeigen, was hätte sein können...\"" }
entries[129930] = { ["name"] = "Gurons Trommel", ["text"] = "Questgegenstand\n\"Diese mit Leder bezogene Trommel scheint bereits lang in Benutzung, doch wurde sie gut gepflegt.\"" }
