entries[129962] = { ["name"] = "Urhornzaumzeug", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr ein großes Nordurhorn beschwört. Das ist ein Bodenreittier.\nGroßes Nordurhorn : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Lederverarbeitung der Verheerten Inseln (100)\nBenötigt Unerfahrenes Reiten\n\n\"Eine der wackersten Spezies, die auf den Hängen des Hochbergs hausen. Sie können monatelang in eisigen Blizzards überleben.\"\nBeruf:\nLederverarbeitung" }
entries[129963] = { ["name"] = "Steinbalgschuhboden", ["text"] = "Wird beim Aufheben gebunden\n\"Alltagstauglich, jedoch nicht haltbar genug für den Kampf.\"" }
