entries[130900] = { ["name"] = "Opfer bringen für Eure Freunde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\nBenutzen: Der Paladin opfert sich, um das anvisierte Gruppenmitglied vor Schaden zu bewahren. Es wird komplett immun gegen alle Schaden verursachenden Angriffe und Gegner greifen es nicht mehr an. Es kann jedoch 3 Min. lang keinerlei Aktionen ausführen.\n\nKann nur auf den Verheerten Inseln und im Sanktum des Lichts genutzt werden.\n\"- Von Bolvar Fordragon\"" }
